static ll dfs(int u) {
    ll sum = 0;
    int k = children[u].sz;
    if (k == 0) return tools[u].a;

    ll *gain = (ll *)malloc((size_t)k * sizeof(ll));
    ll *cost = (ll *)malloc((size_t)k * sizeof(ll));

    for (int i = 0; i < k; i++) {
        int v = children[u].v[i];
        cost[i] = dfs(v);
        sum += cost[i];
        gain[i] = tools[v].a - tools[v].b;
        if (gain[i] < 0) gain[i] = 0;
    }

    // To build u first, every child v can be reduced from a[v] to b[v].
    // Total = a[u] + sum(cost[child]) - sum(max(0, a[v]-b[v]))
    ll best = tools[u].a + sum;
    ll save = 0;
    for (int i = 0; i < k; i++) save += gain[i];
    ll cand = tools[u].a + sum - save;
    if (cand < best) best = cand;

    free(gain);
    free(cost);
    return best;
}

