        if (u < 0) return INF;
        if (state[u] == 2) return memo[u];
        if (state[u] == 1) {
            // cycle reached through support chain; only direct option can safely resolve
            return tools[u].direct;
        }
        state[u] = 1;

        long ans = tools[u].direct;
        if (tools[u].support != -1) {
            long sub = solve(tools[u].support);
            if (sub < INF / 2) {
                ans = Math.min(ans, sub + tools[u].withSupport);
            }
        }

        state[u] = 2;
        memo[u] = ans;
        return ans;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        tools = new Tool[n];

        for (int i = 0; i < n; i++) {
            Tool t = new Tool();
            t.name = fs.next();
            t.direct = fs.nextLong();
            t.supportName = fs.next();
            t.withSupport = fs.nextLong();
            tools[i] = t;
            id.put(t.name, i);
        }

        for (int i = 0; i < n; i++) {
            String s = tools[i].supportName;
            if (s.equals("-") || s.equals("0") || s.equalsIgnoreCase("NONE")) {
                tools[i].support = -1;
            } else {
                Integer v = id.get(s);
                tools[i].support = (v == null ? -1 : v);
            }
        }

        memo = new long[n];
        state = new int[n];

        long total = 0;
        for (int i = 0; i < n; i++) {
            total += solve(i);
        }

        System.out.println(total);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
